  private function projectCreateForm(PDO $pdo):string{$clients=$pdo->query('select id::text as id,name from public.smollan_clients order by name')->fetchAll(PDO::FETCH_ASSOC);$stores=$pdo->query("select id::text as id,name,city from public.smollan_stores where status='Active' order by city,name limit 1000")->fetchAll(PDO::FETCH_ASSOC);$h='<section class="panel" id="create-project"><div class="section-head"><div><span class="eyebrow">PROJECT SETUP</span><h2>Create project</h2></div></div><p class="muted">Choose modules at creation. Store supervisor mappings are inherited automatically when stores are linked.</p><form method="post" action="/project/create">'.Csrf::field().'<div class="form-grid"><label>Client<select name="client_id" required><option value="">Select client</option>';foreach($clients as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['name']).'</option>';$h.='</select></label><label>Project name<input name="name" required maxlength="180"></label><label>Service type<select name="service_type"><option value="activation">Activation</option><option value="permanent_promoters">Permanent promoters</option><option value="production_only">Production only</option><option value="in_store_animation">In-store animation</option><option value="merchandising">Merchandising</option></select></label><label>Cadence<select name="cadence"><option value="none">Not recurring</option><option value="VSD">VSD</option><option value="SD">SD</option></select></label><label>Start date<input type="date" name="start_date"></label><label>End date<input type="date" name="end_date"></label><label>Budget (MAD)<input type="number" min="0" step="0.01" name="budget"></label><label>Cities<input name="cities" placeholder="Casablanca, Rabat, Marrakech"></label></div><div class="field-group"><b>Modules</b><div class="module-picks"><label><input type="checkbox" name="modules[]" value="goodies"> Goodies / gifts</label><label><input type="checkbox" name="modules[]" value="plv"> PLV / POSM</label><label><input type="checkbox" name="modules[]" value="uniforms"> Uniforms</label></div></div><label>Initial stores <span class="muted small">(multi-select)</span><select name="store_ids[]" multiple size="7">';foreach($stores as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['name'].' · '.($x['city']??'City not set')).'</option>';$h.='</select></label><button class="button primary">Create project & open dashboard →</button></form></section>';return $h;}
