ype="date" name="deadline"></label><label>Status<select name="status"><option>Planning</option><option>In Production</option><option>Ready</option><option>Delivered</option></select></label>';else $h.='<label>SKU code<input name="sku" required></label><label>Size<input name="size"></label><label>Color<input name="color"></label><label>Quantity on hand<input type="number" min="0" name="quantity" value="0"></label><label>Reorder level<input type="number" min="0" name="reorder_level" value="0"></label><label>Unit cost (MAD)<input type="number" min="0" step="0.01" name="unit_cost" value="0"></label>';$h.='<label class="wide">Description / notes<textarea name="description"></textarea></label></div><button class="button primary">Save item →</button></form></section>';return $h;}
