   if(Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations','supervisor')){$promoters=$pdo->query("select id::text as id,full_name,city from public.smollan_promoters where status<>'Inactive' order by full_name limit 2000")->fetchAll(PDO::FETCH_ASSOC);$h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">TEAM ASSIGNMENT</span><h2>Assign promoter to a store</h2></div></div><form method="post" action="/project/'.Http::e($projectId).'/assignment">'.Csrf::field().'<div class="form-grid"><label>Store<select name="store_id" required><option value="">Choose linked store</option>';foreach($d['stores'] as $s)$h.='<option value="'.Http::e($s['store_id']).'">'.Http::e($s['store_name']).'</option>';$h.='</select></label><label>Promoter<select name="promoter_id" required><option value="">Choose promoter</option>';foreach($promoters as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['full_name'].' · '.($x['city']??'')).'</option>';$h.='</select></label><label>Start date<input type="date" name="start_date" value="'.date('Y-m-d').'" required></label><label>End date<input type="date" name="end_date"></label></div><button class="button primary">Assign promoter →</button></form>';if($d['assignments']){$h.='<div class="table-wrap"><table><thead><tr><th>Promoter</th><th>Store</th><th>Supervisor</th><th>Period</th><th>Status</th><th>Check-in link</th></tr></thead><tbody>';foreach($d['assignments'] as $a){$h.='<tr><td>'.Http::e($a['full_name']).'</td><td>'.Http::e($a['store_name']).'</td><td>'.Http::e($a['supervisor_name']??'—').'</td><td>'.Http::e($a['start_date'].' → '.($a['end_date']??'ongoing')).'</td><td>'.Http::e($a['status']).'</td><td>';if($a['status']==='Active')$h.='<form method="post" action="/assignment/'.Http::e($a['id']).'/checkin-link">'.Csrf::field().'<button class="button subtle">Create link</button></form>';else $h.='—';$h.='</td></tr>';}$h.='</tbody></table></div>';}$h.='</section>';}
