  private function absoluteUrl(string $path):string{$base=rtrim((string)Env::get('APP_BASE_URL',''),'/');if($base!=='')return $base.$path;$host=(string)($_SERVER['HTTP_HOST']??'');if(!preg_match('/^[a-zA-Z0-9.-]+(?::[0-9]{1,5})?$/',$host))throw new \RuntimeException('Set APP_BASE_URL to create shareable links.');return 'https://'.$host.$path;}
  private function shareLinkPage(string $title,string $url,string $note):void{$h='<section class="panel"><span class="eyebrow">LINK CREATED</span><h1>'.Http::e($title).'</h1><p>'.Http::e($note).'</p><label>Copy link<input readonly value="'.Http::e($url).'" onclick="this.select()"></label><p><a class="button primary" href="'.Http::e($url).'" target="_blank" rel="noopener">Open link ↗</a> <a class="button subtle" href="/projects">Back to projects</a></p></section>';$this->layout($title,$h);}

  private function projectExecutionPanel(PDO $pdo,string $projectId,array $project):string{
  $can=Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations','supervisor');
  $h='<section class="panel"><div class="section-head"><div><span class="eyebrow">PROJECT TIMELINE</span><h2>Working days & activation calendar</h2></div></div>';
  $q=$pdo->prepare("select wd.work_date,wd.is_activation_day,wd.planned_promoters,wd.notes,s.name as store_name from public.smollan_project_working_days wd left join public.smollan_stores s on s.id=wd.store_id where wd.project_id=cast(:p as uuid) order by wd.work_date, s.name");
  $q->execute(['p'=>$projectId]);$days=$q->fetchAll(PDO::FETCH_ASSOC);
  if($days){$h.='<div class="table-wrap"><table><thead><tr><th>Date</th><th>Activation day</th><th>Store</th><th>Planned promoters</th><th>Notes</th></tr></thead><tbody>';foreach($days as $day)$h.='<tr><td>'.Http::e($day['work_date']).'</td><td>'.($day['is_activation_day']?'Yes':'No').'</td><td>'.Http::e($day['store_name']??'All project stores').'</td><td>'.(int)$day['planned_promoters'].'</td><td>'.Http::e($day['notes']).'</td></tr>';$h.='</tbody></table></div>';}else $h.='<p class="muted">No working days planned yet. Add activation days to populate the admin calendar and daily goodies quotas.</p>';
  if($can){$stores=$pdo->prepare("select s.id::text,s.name from public.smollan_project_stores ps join public.smollan_stores s on s.id=ps.store_id where ps.project_id=cast(:p as uuid) order by s.name");$stores->execute(['p'=>$projectId]);$storeRows=$stores->fetchAll(PDO::FETCH_ASSOC);$h.='<form method="post" action="/project/'.Http::e($projectId).'/working-day">'.Csrf::field().'<div class="form-grid"><label>Date<input type="date" name="work_date" required></label><label>Store<select name="store_id"><option value="">All project stores</option>';foreach($storeRows as $s)$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['name']).'</option>';$h.='</select></label><label>Planned promoters<input type="number" min="0" name="planned_promoters" value="0"></label><label>Notes<input name="notes" maxlength="500"></label></div><label><input type="checkbox" name="is_activation_day" value="1" checked> This is an activated working day</label><button class="button subtle">Add / update working day</button></form>';}
  $h.='</section><section class="panel"><div class="section-head"><div><span class="eyebrow">TASK BOARD</span><h2>Project kanban</h2></div><span class="muted small">Backlog → To do → In progress → Blocked / Review → Done</span></div>';
  $t=$pdo->prepare("select id::text,title,status,priority,task_type,due_date,coalesce(pr.full_name,'Unassigned') as owner from public.smollan_project_tasks t left join public.smollan_promoters pr on pr.id=t.owner_promoter_id where t.project_id=cast(:p as uuid) order by case priority when 'urgent' then 0 when 'high' then 1 when 'medium' then 2 else 3 end,due_date nulls last,created_at desc");$t->execute(['p'=>$projectId]);$tasks=$t->fetchAll(PDO::FETCH_ASSOC);
  $columns=['backlog'=>'Backlog','todo'=>'To do','in_progress'=>'In progress','blocked'=>'Blocked','review'=>'Review','done'=>'Done'];
  $h.='<div class="module-grid">';
  foreach($columns as $key=>$label){$subset=array_values(array_filter($tasks,fn($x)=>$x['status']===$key));$h.='<section class="panel"><h3>'.Http::e($label).' <small>('.count($subset).')</small></h3>';foreach($subset as $task)$h.='<article class="task-card"><b>'.Http::e($task['title']).'</b><p class="muted small">'.Http::e($task['task_type']).' · '.Http::e($task['priority']).'</p><p class="small">'.Http::e($task['owner']).' · due '.Http::e($task['due_date']??'—').'</p>'.($can?'<form method="post" action="/project/'.Http::e($projectId).'/task">'.Csrf::field().'<input type="hidden" name="task_id" value="'.Http::e($task['id']).'"><select name="status">'.implode('',array_map(fn($k)=>'<option value="'.Http::e($k).'"'.($k===$task['status']?' selected':'').'>'.Http::e($columns[$k]).'</option>',array_keys($columns))).'</select><button class="button subtle">Move</button></form>':'').'</article>';if(!$subset)$h.='<p class="muted small">No tasks</p>';$h.='</section>';}
  $h.='</div>';
  if($can)$h.='<form method="post" action="/project/'.Http::e($projectId).'/task">'.Csrf::field().'<div class="form-grid"><label>Task title<input name="title" required maxlength="180"></label><label>Type<select name="task_type"><option value="general">General</option><option value="planning">Planning</option><option value="store_activation">Store activation</option><option value="recruitment">Recruitment</option><option value="posm">POSM</option><option value="goodies">Goodies</option><option value="uniforms">Uniforms</option><option value="attendance">Attendance</option><option value="reporting">Reporting</option><option value="procurement">Procurement</option><option value="finance">Finance</option></select></label><label>Priority<select name="priority"><option>medium</option><option>low</option><option>high</option><option>urgent</option></select></label><label>Status<select name="status"><option value="backlog">Backlog</option><option value="todo">To do</option><option value="in_progress">In progress</option></select></label><label>Start date<input type="date" name="start_date"></label><label>Due date<input type="date" name="due_date"></label><label class="wide">Description<textarea name="description"></textarea></label></div><button class="button primary">Create task</button></form>';
  $h.='</section>';
  $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">DELIVERABLES LIFECYCLE</span><h2>POSM & goodies milestones</h2></div></div>';
  $q=$pdo->prepare("select d.id::text,d.deliverable_type,d.name,d.quantity,d.design_status,d.production_status,d.dispatch_status,d.installation_status,d.return_dispatch_status,d.returned_quantity,d.production_start_date,d.production_due_date,d.production_completed_at::date as production_completed_at,d.dispatched_at::date as dispatched_at,d.installation_due_date,d.installed_at::date as installed_at,d.return_due_date,d.returned_at::date as returned_at,d.dispatch_reference,d.installation_evidence_url from public.smollan_project_deliverables d where d.project_id=cast(:p as uuid) order by d.deliverable_type,d.name");$q->execute(['p'=>$projectId]);$deliverables=$q->fetchAll(PDO::FETCH_ASSOC);
  if($deliverables){$h.='<div class="table-wrap"><table><thead><tr><th>Type / item</th><th>Qty</th><th>Design validation</th><th>Production</th><th>Dispatch</th><th>Installation</th><th>Return after project</th><th>Returned</th></tr></thead><tbody>';foreach($deliverables as $d)$h.='<tr><td>'.Http::e(strtoupper($d['deliverable_type']).' · '.$d['name']).'</td><td>'.(int)$d['quantity'].'</td><td>'.Http::e($d['design_status']).'</td><td>'.Http::e($d['production_status']).'</td><td>'.Http::e($d['dispatch_status']).'</td><td>'.Http::e($d['installation_status']).'</td><td>'.Http::e($d['return_dispatch_status']).'</td><td>'.(int)$d['returned_quantity'].'</td></tr>';$h.='</tbody></table></div>';}else $h.='<p class="muted">No lifecycle records yet. Create one for each item requiring design, production, dispatch, installation or return tracking.</p>';
  if($can){$g=$pdo->prepare("select id::text,name from public.smollan_gifts where project_id=cast(:p as uuid) order by name");$g->execute(['p'=>$projectId]);$gifts=$g->fetchAll(PDO::FETCH_ASSOC);$plv=$pdo->prepare("select id::text,name from public.smollan_plv_materials where project_id=cast(:p as uuid) order by name");$plv->execute(['p'=>$projectId]);$plvs=$plv->fetchAll(PDO::FETCH_ASSOC);
    $h.='<form method="post" action="/project/'.Http::e($projectId).'/deliverable">'.Csrf::field().'<div class="form-grid"><label>Type<select name="deliverable_type"><option value="posm">POSM / PLV</option><option value="goodie">Goodie</option></select></label><label>Item name<input name="name" required maxlength="180"></label><label>Quantity<input type="number" name="quantity" min="0" value="0" required></label><label>Existing item (optional)<select name="item_id"><option value="">Create standalone tracker</option>';foreach($plvs as $x)$h.='<option value="plv:'.Http::e($x['id']).'">POSM · '.Http::e($x['name']).'</option>';foreach($gifts as $x)$h.='<option value="goodie:'.Http::e($x['id']).'">Goodie · '.Http::e($x['name']).'</option>';$h.='</select></label></div><button class="button primary">Add lifecycle tracker</button></form>';
    if($deliverables){$dopts=['design_status'=>['not_started','in_progress','submitted','client_review','changes_requested','validated','not_applicable'],'production_status'=>['not_started','quoted','approved','in_production','quality_check','completed','on_hold','not_applicable'],'dispatch_status'=>['not_ready','ready','partially_dispatched','dispatched','delivered','not_applicable'],'installation_status'=>['not_applicable','pending','scheduled','in_progress','installed','failed','verified'],'return_dispatch_status'=>['not_applicable','pending','scheduled','collected','in_transit','received','reconciled','missing_items']];foreach($deliverables as $d){$h.='<form method="post" class="inline-form" action="/project/'.Http::e($projectId).'/deliverable">'.Csrf::field().'<input type="hidden" name="deliverable_id" value="'.Http::e($d['id']).'"><b>'.Http::e($d['name']).'</b>';foreach($dopts as $field=>$opts){$h.='<label>'.Http::e(str_replace('_',' ',$field)).'<select name="'.Http::e($field).'">';foreach($opts as $opt)$h.='<option value="'.Http::e($opt).'"'.($opt===$d[$field]?' selected':'').'>'.Http::e($opt).'</option>';$h.='</select></label>';}$h.='<label>Production start<input type="date" name="production_start_date" value="'.Http::e($d['production_start_date']??'').'"></label><label>Production due<input type="date" name="production_due_date" value="'.Http::e($d['production_due_date']??'').'"></label><label>Production completed<input type="date" name="production_completed_at" value="'.Http::e($d['production_completed_at']??'').'"></label><label>Dispatch date<input type="date" name="dispatched_at" value="'.Http::e($d['dispatched_at']??'').'"></label><label>Installation due<input type="date" name="installation_due_date" value="'.Http::e($d['installation_due_date']??'').'"></label><label>Installed date<input type="date" name="installed_at" value="'.Http::e($d['installed_at']??'').'"></label><label>Return due<input type="date" name="return_due_date" value="'.Http::e($d['return_due_date']??'').'"></label><label>Returned date<input type="date" name="returned_at" value="'.Http::e($d['returned_at']??'').'"></label><label>Dispatch reference<input name="dispatch_reference" maxlength="180" value="'.Http::e($d['dispatch_reference']??'').'"></label><label>Installation evidence URL<input type="url" name="installation_evidence_url" value="'.Http::e($d['installation_evidence_url']??'').'"></label><label>Returned qty<input type="number" name="returned_quantity" min="0" max="'.(int)$d['quantity'].'" value="'.(int)$d['returned_quantity'].'"></label><button class="button subtle">Update milestones</button></form>';}}
  }
  $h.='</section>';return $h;
}
private function projectExecutionAction(PDO $pdo,string $projectId,string $action):void{
 if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}
 try{
  if(!Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations','supervisor'))throw new RuntimeException('You cannot change this project workflow.');
  if($action==='task'){
   if(!empty($_POST['task_id'])){$status=(string)($_POST['status']??'todo');if(!in_array($status,['backlog','todo','in_progress','blocked','review','done'],true))throw new RuntimeException('Invalid task status.');$q=$pdo->prepare("update public.smollan_project_tasks set status=:s,completed_at=case when :s='done' then now() else null end,updated_at=now() where id=cast(:id as uuid) and project_id=cast(:p as uuid)");$q->execute(['s'=>$status,'id'=>$_POST['task_id'],'p'=>$projectId]);}
   else{$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Task title is required.');$status=(string)($_POST['status']??'backlog');$priority=(string)($_POST['priority']??'medium');$type=(string)($_POST['task_type']??'general');if(!in_array($status,['backlog','todo','in_progress'],true)||!in_array($priority,['low','medium','high','urgent'],true)||!in_array($type,['planning','store_activation','recruitment','posm','goodies','uniforms','attendance','reporting','procurement','finance','general'],true))throw new RuntimeException('Invalid task configuration.');$q=$pdo->prepare("insert into public.smollan_project_tasks(project_id,title,description,status,priority,task_type,start_date,due_date,created_by) values(cast(:p as uuid),:title,:description,:status,:priority,:type,:start,:due,cast(:u as uuid))");$q->execute(['p'=>$projectId,'title'=>$title,'description'=>trim((string)($_POST['description']??'')),'status'=>$status,'priority'=>$priority,'type'=>$type,'start'=>trim((string)($_POST['start_date']??''))?:null,'due'=>trim((string)($_POST['due_date']??''))?:null,'u'=>Auth::user()['id']]);}
  }elseif($action==='working-day'){
   $date=(string)($_POST['work_date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Choose a valid working date.');$store=trim((string)($_POST['store_id']??''))?:null;$planned=max(0,(int)($_POST['planned_promoters']??0));$q=$pdo->prepare("insert into public.smollan_project_working_days(project_id,store_id,work_date,is_activation_day,planned_promoters,notes,created_by) values(cast(:p as uuid),cast(:s as uuid),:d,:active,:planned,:notes,cast(:u as uuid)) on conflict(project_id,store_id,work_date) do update set is_activation_day=excluded.is_activation_day,planned_promoters=excluded.planned_promoters,notes=excluded.notes");$q->execute(['p'=>$projectId,'s'=>$store,'d'=>$date,'active'=>isset($_POST['is_activation_day']),'planned'=>$planned,'notes'=>trim((string)($_POST['notes']??'')),'u'=>Auth::user()['id']]);
  }else{
   if(!empty($_POST['deliverable_id'])){$id=(string)$_POST['deliverable_id'];$allowed=['design_status'=>['not_started','in_progress','submitted','client_review','changes_requested','validated','not_applicable'],'production_status'=>['not_started','quoted','approved','in_production','quality_check','completed','on_hold','not_applicable'],'dispatch_status'=>['not_ready','ready','partially_dispatched','dispatched','delivered','not_applicable'],'installation_status'=>['not_applicable','pending','scheduled','in_progress','installed','failed','verified'],'return_dispatch_status'=>['not_applicable','pending','scheduled','collected','in_transit','received','reconciled','missing_items']];$set=[];$params=['id'=>$id,'p'=>$projectId];foreach($allowed as $field=>$values){$value=(string)($_POST[$field]??'');if($value!==''&&in_array($value,$values,true)){$set[]=$field.'=:'.$field;$params[$field]=$value;}}$returned=max(0,(int)($_POST['returned_quantity']??0));$set[]='returned_quantity=:returned';$params['returned']=$returned;foreach(['production_start_date','production_due_date','production_completed_at','dispatched_at','installation_due_date','installed_at','return_due_date','returned_at'] as $field){$value=trim((string)($_POST[$field]??''));$set[]=$field.'=:'.$field;$params[$field]=$value!==''?$value:null;}foreach(['dispatch_reference','installation_evidence_url'] as $field){$value=trim((string)($_POST[$field]??''));$set[]=$field.'=:'.$field;$params[$field]=$value!==''?$value:null;}if(($params['design_status']??'')==='validated'){$set[]='design_validated_at=coalesce(design_validated_at,now())';$set[]='design_validated_by=coalesce(design_validated_by,cast(:validator as uuid))';$params['validator']=Auth::user()['id'];}$set[]='updated_at=now()';$q=$pdo->prepare('update public.smollan_project_deliverables set '.implode(',',$set).' where id=cast(:id as uuid) and project_id=cast(:p as uuid)');$q->execute($params);}
   else{$type=(string)($_POST['deliverable_type']??'');$name=trim((string)($_POST['name']??''));$qty=max(0,(int)($_POST['quantity']??0));if(!in_array($type,['posm','goodie'],true)||$name==='')throw new RuntimeException('Choose a deliverable type and item name.');$item=explode(':',(string)($_POST['item_id']??''),2);$plvId=$type==='posm'&&($item[0]??'')==='plv'?($item[1]??null):null;$giftId=$type==='goodie'&&($item[0]??'')==='goodie'?($item[1]??null):null;$q=$pdo->prepare("insert into public.smollan_project_deliverables(project_id,deliverable_type,plv_material_id,gift_id,name,quantity,created_by) values(cast(:p as uuid),:type,cast(:plv as uuid),cast(:gift as uuid),:name,:qty,cast(:u as uuid))");$q->execute(['p'=>$projectId,'type'=>$type,'plv'=>$plvId,'gift'=>$giftId,'name'=>$name,'qty'=>$qty,'u'=>Auth::user()['id']]);}
  }
  Http::flash('success','Project execution record saved.');
 }catch(Throwable $e){Http::flash('error',$e->getMessage());}
 Http::redirect('/projects/'.$projectId);
}
private function goodieQuotaAction(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{if(!Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations'))throw new \RuntimeException('Not authorized.');$p=(string)($_POST['project_id']??'');$store=(string)($_POST['store_id']??'');$gift=(string)($_POST['gift_id']??'');$date=(string)($_POST['activation_date']??'');$qty=max(0,(int)($_POST['quota_quantity']??0));$q=$pdo->prepare("insert into public.smollan_goodie_store_day_quotas(project_id,store_id,gift_id,activation_date,quota_quantity,created_by) select cast(:p as uuid),cast(:s as uuid),cast(:g as uuid),:d,:qty,cast(:u as uuid) where exists(select 1 from public.smollan_project_working_days wd where wd.project_id=cast(:p_day as uuid) and wd.store_id=cast(:s_day as uuid) and wd.work_date=:d_day and wd.is_activation_day=true) and exists(select 1 from public.smollan_project_stores ps where ps.project_id=cast(:p_store as uuid) and ps.store_id=cast(:s_store as uuid)) and exists(select 1 from public.smollan_gifts g where g.id=cast(:g_item as uuid) and g.project_id=cast(:p_gift as uuid)) on conflict(project_id,store_id,gift_id,activation_date) do update set quota_quantity=excluded.quota_quantity,updated_at=now()");$q->execute(['p'=>$p,'s'=>$store,'g'=>$gift,'d'=>$date,'qty'=>$qty,'u'=>Auth::user()['id'],'p_day'=>$p,'s_day'=>$store,'d_day'=>$date,'p_store'=>$p,'s_store'=>$store,'g_item'=>$gift,'p_gift'=>$p]);if(!$q->rowCount())throw new \RuntimeException('Create an activated working day for this project/store/date before setting a quota.');Http::flash('success','Daily store quota saved.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/goodies');}
private function goodieDistributionAction(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{if(!Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations','supervisor','promoter'))throw new \RuntimeException('Not authorized to log distributions.');$quota=(string)($_POST['quota_id']??'');$qty=max(1,(int)($_POST['distributed_quantity']??0));$promoter=trim((string)($_POST['promoter_id']??''))?:null;$pdo->beginTransaction();$q=$pdo->prepare("select quota_quantity,coalesce((select sum(distributed_quantity) from public.smollan_goodie_distributions d where d.quota_id=q.id),0) as distributed from public.smollan_goodie_store_day_quotas q where q.id=cast(:id as uuid) for update");$q->execute(['id'=>$quota]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new \RuntimeException('Quota not found.');if((int)$r['distributed']+$qty>(int)$r['quota_quantity'])throw new \RuntimeException('Distribution exceeds the daily quota.');$q=$pdo->prepare("insert into public.smollan_goodie_distributions(quota_id,distributed_quantity,distributed_by,promoter_id,notes,evidence_url) values(cast(:q as uuid),:qty,cast(:u as uuid),cast(:p as uuid),:notes,:evidence)");$q->execute(['q'=>$quota,'qty'=>$qty,'u'=>Auth::user()['id'],'p'=>$promoter,'notes'=>trim((string)($_POST['notes']??'')),'evidence'=>trim((string)($_POST['evidence_url']??''))?:null]);$pdo->commit();Http::flash('success','Goodie distribution recorded within the quota.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Http::flash('error',$e->getMessage());}Http::redirect('/goodies');}
private function promoterProfile(PDO $pdo,string $id):void{$q=$pdo->prepare("select id::text,full_name,phone,email,city,status,contract_type,uniform_size from public.smollan_promoters where id=cast(:id as uuid)");$q->execute(['id'=>$id]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p){Http::flash('error','Promoter not found.');Http::redirect('/promoters');return;}$q=$pdo->prepare("select * from public.smollan_promoter_project_history where promoter_id=cast(:id as uuid) order by assignment_start desc nulls last");$q->execute(['id'=>$id]);$history=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("select a.attendance_date,a.status,a.check_in,a.check_out,a.validation_status,pr.name as project_name,s.name as store_name from public.smollan_attendance a join public.smollan_assignments ass on ass.id=a.assignment_id join public.smollan_projects pr on pr.id=ass.project_id left join public.smollan_stores s on s.id=ass.store_id where ass.promoter_id=cast(:id as uuid) order by a.attendance_date desc limit 500");$q->execute(['id'=>$id]);$attendance=$q->fetchAll(PDO::FETCH_ASSOC);$h='<section class="welcome-row"><div><span class="eyebrow">PERSONNEL HISTORY</span><h1>'.Http::e($p['full_name']).'</h1><p class="muted">'.Http::e(($p['city']??'').' · '.($p['phone']??'').' · '.($p['email']??'')).'</p></div><a class="button subtle" href="/promoters">← Promoters</a></section><section class="metrics"><div class="metric"><span>Projects worked</span><strong>'.count($history).'</strong></div><div class="metric"><span>Attendance records</span><strong>'.array_sum(array_map(fn($x)=>(int)$x['attendance_records'],$history)).'</strong></div><div class="metric"><span>Present days</span><strong>'.array_sum(array_map(fn($x)=>(int)$x['present_days'],$history)).'</strong></div></section><section class="panel"><h2>Project history</h2><div class="table-wrap"><table><thead><tr><th>Project</th><th>Store</th><th>Period</th><th>Assignment status</th><th>Attendance</th><th>Present</th><th>Absent</th></tr></thead><tbody>';foreach($history as $x)$h.='<tr><td>'.Http::e($x['project_name']).'</td><td>'.Http::e($x['store_name']??'—').'</td><td>'.Http::e(($x['assignment_start']??'—').' → '.($x['assignment_end']??'ongoing')).'</td><td>'.Http::e($x['assignment_status']).'</td><td>'.(int)$x['attendance_records'].'</td><td>'.(int)$x['present_days'].'</td><td>'.(int)$x['absent_days'].'</td></tr>';$h.='</tbody></table></div></section><section class="panel"><h2>Attendance history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Project</th><th>Store</th><th>Status</th><th>Check-in</th><th>Check-out</th><th>Validation</th></tr></thead><tbody>';foreach($attendance as $a)$h.='<tr><td>'.Http::e($a['attendance_date']).'</td><td>'.Http::e($a['project_name']).'</td><td>'.Http::e($a['store_name']??'—').'</td><td>'.Http::e($a['status']).'</td><td>'.Http::e($a['check_in']??'—').'</td><td>'.Http::e($a['check_out']??'—').'</td><td>'.Http::e($a['validation_status']??'—').'</td></tr>';$h.='</tbody></table></div></section>';$this->layout('Promoter profile',$h);}
  private function renderPromoterTable(PDO $pdo,array $rows):string{if(!$rows)return $this->renderTable($rows);$h='<div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>City</th><th>Status</th><th>Login</th></tr></thead><tbody>';foreach($rows as $r){$q=$pdo->prepare('select user_id::text from public.smollan_promoters where id=cast(:id as uuid)');$q->execute(['id'=>$r['id']]);$userId=$q->fetchColumn();$h.='<tr><td>'.'<a href="/promoter/'.Http::e($r['id']).'">'.Http::e($r['full_name']??'—').'</a></td><td>'.Http::e($r['phone']??'—').'</td><td>'.Http::e($r['email']??'—').'</td><td>'.Http::e($r['city']??'—').'</td><td>'.Http::e($r['status']??'—').'</td><td>';if($userId)$h.='<span class="status-pill">Account linked</span>';elseif(!empty($r['email'])&&Auth::can('platform_admin','leadership','activation_coordinator','field_manager','hr_coordinator'))$h.='<form method="post" action="/promoter/'.Http::e($r['id']).'/invite">'.Csrf::field().'<button class="button subtle">Email login invite</button></form>';else $h.='<span class="muted small">Add email</span>';$h.='</td></tr>'; }return $h.'</tbody></table></div>';}
  private function storeSupervisorForm(PDO $pdo):string{$stores=$pdo->query("select id::text as id,name,city from public.smollan_stores where status='Active' order by name")->fetchAll(PDO::FETCH_ASSOC);$supers=$pdo->query("select id::text as id,full_name,city from public.smollan_supervisors where status='Active' order by full_name")->fetchAll(PDO::FETCH_ASSOC);$h='<section class="panel"><div class="section-head"><div><span class="eyebrow">AUTOMATIC PROJECT ROUTING</span><h2>Map supervisors to stores</h2></div></div><p class="muted">When a mapped store is added to a project, its primary supervisor is assigned automatically.</p><form method="post" action="/store-supervisor/create">'.Csrf::field().'<div class="form-grid"><label>Store<select name="store_id" required><option value="">Choose store</option>';foreach($stores as $s)$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['name'].' · '.($s['city']??'')).'</option>';$h.='</select></label><label>Supervisor<select name="supervisor_id" required><option value="">Choose supervisor</option>';foreach($supers as $s)$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['full_name'].' · '.($s['city']??'')).'</option>';$h.='</select></label></div><label><input type="checkbox" name="is_primary" value="1" checked> Set as primary supervisor for this store</label><button class="button primary">Save store supervisor mapping →</button></form></section>';return $h;}
  private function mapStoreSupervisor(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->mapSupervisorToStore((string)($_POST['store_id']??''),(string)($_POST['supervisor_id']??''),isset($_POST['is_primary']));Http::flash('success','Store supervisor mapping saved. Existing project-store links without a supervisor were updated.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/supervisors');}
  private function invitePromoter(PDO $pdo,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->invitePromoter($id);Http::flash('success','Supabase invitation sent. The promoter can set their password from the invite email.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/promoters');}
  private function promoterPortal(PDO $pdo):void{$uid=(string)(Auth::user()['id']??'');$q=$pdo->prepare("select id::text,full_name from public.smollan_promoters where user_id=cast(:id as uuid) and status<>'Inactive'");$q->execute(['id'=>$uid]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p){Auth::logout();Http::redirect('/login');return;}$q=$pdo->prepare("select a.id::text as assignment_id,a.start_date,a.end_date,pr.name as project_name,s.name as store_name,s.city,(select at.id::text from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as attendance_id,(select at.check_in from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as check_in,(select at.check_out from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as check_out from public.smollan_assignments a join public.smollan_projects pr on pr.id=a.project_id join public.smollan_stores s on s.id=a.store_id where a.promoter_id=cast(:promoter as uuid) and a.status='Active' and a.start_date<=current_date and (a.end_date is null or a.end_date>=current_date) order by pr.name,s.name");$q->execute(['promoter'=>$p['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$h='<section class="welcome-row"><div><span class="eyebrow">PROMOTER SELF-SERVICE</span><h1>Hello, '.Http::e($p['full_name']).'</h1><p class="muted">Your active assignments and attendance for today.</p></div></section>';if(!$rows)$h.='<section class="panel"><h2>No active assignments</h2><p class="muted">Contact your supervisor if this is unexpected.</p></section>';foreach($rows as $a){$h.='<section class="panel"><h2>'.Http::e($a['project_name']).'</h2><p class="muted">'.Http::e($a['store_name'].' · '.($a['city']??'')).'</p><p>Shift: '.Http::e($a['start_date'].' → '.($a['end_date']??'ongoing')).'</p>';if(empty($a['check_in']))$h.='<form method="post" action="/attendance/check-in">'.Csrf::field().'<input type="hidden" name="assignment_id" value="'.Http::e($a['assignment_id']).'"><button class="button primary">Check in now →</button></form>';elseif(empty($a['check_out']))$h.='<p class="status-pill">Checked in at '.Http::e($a['check_in']).'</p><form method="post" action="/attendance/check-out">'.Csrf::field().'<input type="hidden" name="attendance_id" value="'.Http::e($a['attendance_id']).'"><button class="button primary">Check out →</button></form>';else $h.='<p class="status-pill">Shift completed · '.Http::e($a['check_out']).'</p>';$h.='</section>';}$this->layout('Promoter portal',$h);}
private function layout(string $title,string $body,bool $authenticated=true):void{header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(self), geolocation=(), microphone=()');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");$u=Auth::user();$m=Auth::membership();$flash=Http::takeFlash();echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b38"><title>'.Http::e($title).' · SMOLLAN Operations</title><link rel="stylesheet" href="/assets/app.css"></head><body>';
  if($authenticated&&$u){$nav=[['overview','Overview'],['clients','Clients'],['projects','Projects'],['tasks','Tasks'],['promoters','Promoters'],['stores','Stores'],['supervisors','Supervisors'],['attendance','Attendance'],['surveys','Surveys'],['goodies','Goodies'],['posm','PLV / POSM'],['uniforms','Uniforms'],['assets','Assets'],['hr','HR / PEC'],['resources','Requests'],['quotations','Quotations'],['procurement','Supplier POs'],['finance','Finance'],['whatsapp','WhatsApp groups'],['integrations','Google Workspace'],['imports','Import center']];echo '<aside class="sidebar"><a class="wordmark" href="/"><span class="mark">s.</span><span><b>SMOLLAN</b><small>MOROCCO OPERATIONS</small></span></a><div class="workspace"><span class="workspace-indicator"></span><div><b>Operations workspace</b><small>All activations · MAD</small></div></div><div class="nav-heading">WORKSPACE</div><nav>';foreach($nav as [$slug,$label])if(Policy::allows($slug==='overview'?'overview':($slug==='integrations'?'integrations':$slug)))echo '<a class="nav-link'.(trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/')===$slug?' current':'').'" href="/'.Http::e($slug).'"><span class="nav-glyph">'.Http::e(substr($label,0,1)).'</span>'.Http::e($label).'</a>';echo '</nav><div class="side-bottom"><small>PRIVATE OPERATIONS DATA</small><span>PostgreSQL · RLS enabled</span></div></aside><main class="main"><header class="topbar"><div><span class="crumb">SMOLLAN / </span><b>'.Http::e($title).'</b></div><div class="top-user"><span class="avatar">'.Http::e(strtoupper(substr($u['email']??'SM',0,1))).'</span><div><b>'.Http::e($u['email']??'SMOLLAN User').'</b><small>'.Http::e(str_replace('_',' ',$m['role']??'member')).'</small></div><form action="/logout" method="post">'.Csrf::field().'<button class="logout">Sign out</button></form></div></header><div class="content">';}
  if($flash)echo '<div class="alert '.Http::e($flash['type']??'info').'">'.Http::e($flash['message']??'').'</div>';echo $body;if($authenticated&&$u)echo '</div><footer>SMOLLAN Morocco · Confidential operational data · '.date('Y').'</footer></main>';echo '<script src="/assets/app.js" defer></script></body></html>';}
 private function staticAsset(string $path):void{$file=realpath(dirname(__DIR__).'/public'.$path);$base=realpath(dirname(__DIR__).'/public/assets');if(!$file||!$base||!str_starts_with($file,$base)||!is_file($file)){http_response_code(404);exit;}$ext=pathinfo($file,PATHINFO_EXTENSION);header('Content-Type: '.($ext==='css'?'text/css':($ext==='js'?'application/javascript':'application/octet-stream')));readfile($file);}
}